                            and ids[ny][nx] == -1):
                        ids[ny][nx] = k
                        q.append((ny, nx))
            comps.append(cells)

    seen = [[False] * w for _ in range(h)]
    cavity_components = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c] or seen[r][c]:
                continue
            region = []
            seen[r][c] = True
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                region.append((y, x))
